use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let cents = input.as_i64().unwrap();
    let pounds = cents / 100000000.0;
    let rounded_pounds = pounds.round();
    let rounded_pounds_str = format!("{:.2}", rounded_pounds);
    serde_json::Value::String(rounded_pounds_str)
}
